package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.personality.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.stress.*; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
class Phase4BehaviorAcceptanceTest { @Test void hostileNpcLeaves(){UUID n=UUID.randomUUID(),p=UUID.randomUUID(); var r=new Relationship(n,p,0,0,0,0,0,50,0); var profile=new PersonalityProfile(n); assertEquals(NpcDecision.LEAVE,new NpcBehaviorEngine().decide(NpcActivity.IDLE,r,profile,new NpcStress(0)));} @Test void stressIsBounded(){assertEquals(100,new NpcStress(150).value()); assertEquals(0,new NpcStress(-1).value());} @Test void personalityValuesAreBounded(){var p=new PersonalityProfile(UUID.randomUUID());p.set(PersonalityTrait.BRAVE,150);assertEquals(100,p.strength(PersonalityTrait.BRAVE));p.set(PersonalityTrait.COWARDLY,-150);assertEquals(-100,p.strength(PersonalityTrait.COWARDLY));}}
